[Trait("Area", "Core")]
[Trait("OpsSuite", "RetainedRuntimeUnlock")]
[Collection(FakeNknNetworkCollection.Name)]
public sealed class FileTransferRetainedRuntimeUnlockAnalyzerTests : FileTransferOpsScriptsTestBase
{
    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task AnalyzeRetained_ReceiveRecoverySameRouteRuntimeSuccessorLivenessHandoff(
        bool compact)
    {
        if (!OperatingSystem.IsWindows())
        {
            return;
        }

        const string scope =
            "session_id=sess_same_route; transfer_id=transfer_same_route; " +
            "direction=inbound; route=post_tuna_fallback_v6; protocol_version=6; " +
            "live_route_epoch=2; route_publication_generation=3; " +
            "runtime_generation=3; terminal_generation=0; leg_generation=3; " +
            "transport_epoch=1; bridge_recovery_generation=1; " +
            "checkpoint_request_id=(none); data_session_identity=data-session-1; " +
            "data_session_generation=1; receive_recovery_operation_generation=2; " +
            "receive_recovery_operation_authority_id=recovery-authority-2; " +
            "log_writer_id=writer_same_route";
        var messages = new List<string>
        {
            LogLine($"event=filetransfer_receive_recovery_operation_issued; {scope}; execution_state=Issued; proof_identity=(none)"),
            LogLine($"event=filetransfer_receive_recovery_operation_execution_start_decided; {scope}; execution_state=Running; execution_start_status=Started; proof_identity=(none)"),
            LogLine("event=filetransfer_data_session_availability_observed; " +
                "session_id=sess_same_route; transfer_id=transfer_same_route; " +
                "is_available=0; requires_resume_request=1; " +
                "reason=transport_recovered_unproven; handoff_kind=regular_nkn_recovery; " +
                "target_transport=regular_nkn; log_writer_id=writer_same_route"),
            LogLine("event=filetransfer_v6_epoch_started; session_id=sess_same_route; " +
                "transfer_id=transfer_same_route; direction=inbound; transport_epoch=1; " +
                "reason=transport_recovered_unproven; log_writer_id=writer_same_route"),
            LogLine($"event=filetransfer_receive_recovery_operation_invalidated; {scope}; execution_state=Invalidated; proof_identity=(none); decision_reason=runtime_scope_replaced"),
            LogLine("event=nkn_bridge_recovery_execution_completion_late; " +
                "session_id=sess_same_route; transfer_id=transfer_same_route; direction=inbound; " +
                "runtime_generation=3; leg_generation=3; transport_epoch=1; " +
                "bridge_recovery_generation=1; total_deadline_expired=0; " +
                "log_writer_id=writer_same_route"),
            LogLine("event=filetransfer_route_hint_authorized_publication_accepted; " +
                "session_id=sess_same_route; transfer_id=transfer_same_route; direction=inbound; " +
                "route=post_tuna_fallback_v6; protocol_version=6; live_route_epoch=2; " +
                "source=coordinator_route_publication_successor; runtime_generation=4; " +
                "route_publication_generation=4; terminal_generation=0; leg_generation=4; " +
                "fallback_transport_epoch=1; fallback_bridge_recovery_generation=1; " +
                "log_writer_id=writer_same_route")
        };

        var result = await RunAnalyzeFixtureAsync(
            messages,
            [],
            compact
                ? new Dictionary<string, string>
                {
                    ["NLINK_FILETRANSFER_RETAINED_ANALYSIS_COMPACT"] = "1"
                }
                : null);

        Assert.True(
            result.Script.ExitCode == 0,
            result.Script.Stdout + Environment.NewLine + result.Script.Stderr);
        var verdict = ReadArtifactReport(
            result.ArtifactDir,
            "filetransfer-operator-verdict.txt");
        Assert.Equal(
            "1",
            verdict["filetransfer_receive_recovery_post_tuna_runtime_successor_liveness_handoff_missing_raw_count"]);
        Assert.Equal(
            "1",
            verdict["filetransfer_receive_recovery_post_tuna_runtime_successor_liveness_handoff_missing_unresolved_count"]);
        Assert.Equal(
            "filetransfer_receive_recovery_post_tuna_runtime_successor_liveness_handoff_missing",
            verdict["first_proof_chain_failure_class"]);
        Assert.Equal(
            "transport_recovered_unproven_same_route_runtime_successor_dropped_active_recovery_liveness_authority",
            verdict["first_proof_chain_failure_reason"]);
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(false, true)]
    [InlineData(true, true)]
    public async Task AnalyzeRetained_ReceiveRecoveryFallbackCheckpointSparsePumpHandoff(
        bool compact,
        bool recovered)
    {
        if (!OperatingSystem.IsWindows())
        {
            return;
        }

        const string operationScope =
            "session_id=sess_checkpoint_pump; transfer_id=transfer_checkpoint_pump; " +
            "direction=outbound; route=post_tuna_fallback_v6; protocol_version=6; " +
            "receive_recovery_operation_generation=3; " +
            "receive_recovery_operation_authority_id=recovery-authority-3; " +
            "log_writer_id=writer_checkpoint_pump";
        const string checkpointScope =
            "session_id=sess_checkpoint_pump; transfer_id=transfer_checkpoint_pump; " +
            "direction=outbound; recovery_operation_generation=3; " +
            "recovery_operation_authority_id=recovery-authority-3; " +
            "effective_checkpoint_request_id=v6-state-refresh-1; " +
            "checkpoint_binding_generation=1; checkpoint_delivery_generation=1; " +
            "frame_fingerprint=frame-1; transport_epoch=1; " +
            "log_writer_id=writer_checkpoint_pump";
        const string pumpScope =
            "session_id=sess_checkpoint_pump; transfer_id=transfer_checkpoint_pump; " +
            "direction=outbound; route=post_tuna_fallback_v6; protocol_version=6; " +
            "live_route_epoch=2; runtime_generation=3; terminal_generation=0; " +
            "leg_generation=3; route_publication_generation=3; route_commit_generation=0; " +
            "data_session_generation=1; log_writer_id=writer_checkpoint_pump";
        var messages = new List<string>
        {
            LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied; {checkpointScope}; delivery_state=held; decision_status=accepted"),
            LogLine($"event=filetransfer_receive_recovery_operation_execution_receipt_applied; {operationScope}; execution_outcome=Completed"),
            LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_resume_decided; {checkpointScope}; physical_epoch=1; outcome=accepted"),
            LogLine("event=filetransfer_v6_regular_nkn_state_refresh_send_queued; " +
                "session_id=sess_checkpoint_pump; transfer_id=transfer_checkpoint_pump; " +
                "request_id=v6-state-refresh-1; source=deferred_replay; " +
                "log_writer_id=writer_checkpoint_pump"),
            LogLine($"event=filetransfer_outbound_sparse_worker_handoff_installed; {pumpScope}; install_generation=44; predecessor_install_generation=43"),
            LogLine("event=filetransfer_v4_feedback_first_success; " +
                "session_id=sess_checkpoint_pump; transfer_id=transfer_checkpoint_pump; " +
                "frame_type=filetransfer.frontier_request.v6; log_writer_id=writer_checkpoint_pump"),
            LogLine($"event=filetransfer_outbound_sparse_worker_handoff_rejected; {pumpScope}; " +
                "install_generation=43; predecessor_install_generation=42; " +
                "stage=state_refresh_sent; decision_reason=install_generation_mismatch")
        };
        if (recovered)
        {
            messages.Add(LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied; {checkpointScope}; delivery_state=delivered; decision_status=accepted"));
            messages.Add(LogLine("event=filetransfer_v6_receiver_state_received; " +
                "session_id=sess_checkpoint_pump; transfer_id=transfer_checkpoint_pump; " +
                "log_writer_id=writer_peer"));
            messages.Add(LogLine($"event=filetransfer_receive_recovery_operation_proof_decision_observed; {operationScope}; decision_status=accepted"));
            messages.Add(LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_lifecycle_advanced; {checkpointScope}; checkpoint_binding_state=accepted"));
            messages.Add(LogLine($"event=runtime_unlock_initial_activation_receive_recovery_hold_decided; {operationScope}; decision_status=Released"));
        }

        var result = await RunAnalyzeFixtureAsync(
            messages,
            [],
            compact
                ? new Dictionary<string, string>
                {
                    ["NLINK_FILETRANSFER_RETAINED_ANALYSIS_COMPACT"] = "1"
                }
                : null);

        Assert.True(
            result.Script.ExitCode == 0,
            result.Script.Stdout + Environment.NewLine + result.Script.Stderr);
        var verdict = ReadArtifactReport(result.ArtifactDir, "filetransfer-operator-verdict.txt");
        Assert.Equal("1", verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing_raw_count"]);
        Assert.Equal("1", verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_sparse_pump_handoff_raw_count"]);
        Assert.Equal(recovered ? "1" : "0", verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_sparse_pump_handoff_recovered_count"]);
        Assert.Equal(recovered ? "0" : "1", verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_sparse_pump_handoff_unresolved_count"]);
        if (!recovered)
        {
            Assert.Equal(
                "filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing",
                verdict["first_proof_chain_failure_class"]);
            Assert.Equal(
                "coordinator_resumed_fallback_checkpoint_delivery_not_committed_after_same_scope_sparse_pump_handoff",
                verdict["first_proof_chain_failure_reason"]);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task AnalyzeRetained_ReceiveRecoveryFallbackCheckpointHeldDeliveryRetiredBeforeResume(
        bool compact)
    {
        if (!OperatingSystem.IsWindows())
        {
            return;
        }

        const string operationScope =
            "session_id=sess_checkpoint_hold; transfer_id=transfer_checkpoint_hold; " +
            "direction=outbound; route=post_tuna_fallback_v6; protocol_version=6; " +
            "receive_recovery_operation_generation=3; " +
            "receive_recovery_operation_authority_id=recovery-authority-3; " +
            "log_writer_id=writer_checkpoint_hold";
        const string checkpointScope =
            "session_id=sess_checkpoint_hold; transfer_id=transfer_checkpoint_hold; " +
            "direction=outbound; recovery_operation_generation=3; " +
            "recovery_operation_authority_id=recovery-authority-3; " +
            "effective_checkpoint_request_id=v6-state-refresh-1; " +
            "checkpoint_binding_generation=1; frame_fingerprint=frame-1; " +
            "transport_epoch=1; log_writer_id=writer_checkpoint_hold";
        var result = await RunAnalyzeFixtureAsync(
            [
                LogLine($"event=filetransfer_receive_recovery_operation_issued; {operationScope}"),
                LogLine($"event=filetransfer_receive_recovery_operation_execution_start_decided; {operationScope}; execution_state=Running"),
                LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_bound; {checkpointScope}; checkpoint_binding_state=pending"),
                LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied; {checkpointScope}; checkpoint_delivery_generation=1; delivery_state=held; decision_status=accepted"),
                LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_lifecycle_advanced; {checkpointScope}; checkpoint_binding_state=retired; decision_reason=tail_reconciliation_forced"),
                LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_invalidated; {checkpointScope}; checkpoint_binding_state=invalidated; decision_reason=runtime_scope_replaced"),
                LogLine($"event=filetransfer_receive_recovery_operation_invalidated; {operationScope}; decision_reason=runtime_scope_replaced")
            ],
            [],
            compact
                ? new Dictionary<string, string>
                {
                    ["NLINK_FILETRANSFER_RETAINED_ANALYSIS_COMPACT"] = "1"
                }
                : null);

        Assert.True(
            result.Script.ExitCode == 0,
            result.Script.Stdout + Environment.NewLine + result.Script.Stderr);
        var verdict = ReadArtifactReport(result.ArtifactDir, "filetransfer-operator-verdict.txt");
        Assert.Equal("1", verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing_raw_count"]);
        Assert.Equal("1", verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing_distinct_count"]);
        Assert.Equal("0", verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing_recovered_count"]);
        Assert.Equal("1", verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing_unresolved_count"]);
        Assert.Equal("1", verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_held_delivery_retired_raw_count"]);
        Assert.Equal("1", verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_held_delivery_retired_unresolved_count"]);
        Assert.Equal(
            "filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing",
            verdict["first_proof_chain_failure_class"]);
        Assert.Equal(
            "held_receive_recovery_fallback_checkpoint_retired_before_exact_resume_boundary",
            verdict["first_proof_chain_failure_reason"]);
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(false, true)]
    [InlineData(true, true)]
    public async Task AnalyzeRetained_ReceiveRecoveryFallbackCheckpointDeliveredResponseTimeoutRequiresCoordinatorRedelivery(
        bool compact,
        bool recovered)
    {
        if (!OperatingSystem.IsWindows())
        {
            return;
        }

        const string operationScope =
            "session_id=sess_checkpoint_timeout; transfer_id=transfer_checkpoint_timeout; " +
            "direction=outbound; route=post_tuna_fallback_v6; protocol_version=6; " +
            "receive_recovery_operation_generation=3; " +
            "receive_recovery_operation_authority_id=recovery-authority-3; " +
            "log_writer_id=writer_checkpoint_timeout";
        const string checkpointScope =
            "session_id=sess_checkpoint_timeout; transfer_id=transfer_checkpoint_timeout; " +
            "direction=outbound; recovery_operation_generation=3; " +
            "recovery_operation_authority_id=recovery-authority-3; " +
            "effective_checkpoint_request_id=v6-regular-nkn-state-refresh:1; " +
            "checkpoint_binding_generation=1; frame_fingerprint=frame-timeout-1; " +
            "transport_epoch=1; log_writer_id=writer_checkpoint_timeout";
        var messages = new List<string>
        {
            LogLine($"event=filetransfer_receive_recovery_operation_issued; {operationScope}"),
            LogLine($"event=filetransfer_receive_recovery_operation_execution_start_decided; {operationScope}; execution_state=Running"),
            LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_bound; {checkpointScope}; checkpoint_binding_state=pending"),
            LogLine($"event=runtime_unlock_initial_activation_receive_recovery_hold_decided; {operationScope}; decision_status=Held"),
            LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied; {checkpointScope}; checkpoint_delivery_generation=1; delivery_state=held; decision_status=accepted"),
            LogLine($"event=filetransfer_receive_recovery_operation_execution_receipt_applied; {operationScope}; execution_outcome=Completed"),
            LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_resume_decided; {checkpointScope}; checkpoint_delivery_generation=1; outcome=accepted")
        };
        var initialPhysicalSend = LogLine(
            "event=filetransfer_v6_regular_nkn_state_refresh_sent; session_id=sess_checkpoint_timeout; " +
            "transfer_id=transfer_checkpoint_timeout; request_id=v6-regular-nkn-state-refresh:1; " +
            "transport_epoch=1; log_writer_id=writer_checkpoint_timeout");
        var initialDelivered = LogLine(
            $"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied; {checkpointScope}; " +
            "checkpoint_delivery_generation=1; delivery_state=delivered; decision_status=accepted");
        messages.Add(initialDelivered);
        messages.Add(initialPhysicalSend);
        messages.Add(LogLine("event=filetransfer_receive_recovery_operation_proof_decision_observed; " +
            "session_id=sess_checkpoint_timeout; transfer_id=transfer_checkpoint_timeout; " +
            "direction=outbound; recovery_operation_generation=3; " +
            "decision_status=Accepted; log_writer_id=writer_checkpoint_timeout"));
        messages.Add(LogLine(
            $"event=runtime_unlock_initial_activation_receive_recovery_hold_decided; {operationScope}; decision_status=Released"));
        for (var index = 0; index < 14; index++)
        {
            messages.Add(LogLine(
                "event=filetransfer_fallback_checkpoint_response_timeout_reissued; " +
                "session_id=sess_checkpoint_timeout; transfer_id=transfer_checkpoint_timeout; " +
                "direction=outbound; checkpoint_request_id=v6-regular-nkn-state-refresh:1; " +
                "transport_epoch=1; log_writer_id=writer_checkpoint_timeout"));
        }
        if (recovered)
        {
            messages.Add(LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_response_timeout_recheck_decided; {checkpointScope}; previous_checkpoint_delivery_generation=1; checkpoint_delivery_generation=2; status=accepted"));
            messages.Add(LogLine("event=filetransfer_v6_regular_nkn_state_refresh_sent; " +
                "session_id=sess_checkpoint_timeout; transfer_id=transfer_checkpoint_timeout; " +
                "request_id=v6-regular-nkn-state-refresh:1; transport_epoch=1; " +
                "log_writer_id=writer_checkpoint_timeout"));
            messages.Add(LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied; {checkpointScope}; checkpoint_delivery_generation=2; delivery_state=delivered; decision_status=accepted"));
            messages.Add(LogLine("event=filetransfer_v6_regular_nkn_state_refresh_received; " +
                "session_id=sess_checkpoint_timeout; transfer_id=transfer_checkpoint_timeout; " +
                "request_id=v6-regular-nkn-state-refresh:1; " +
                "log_writer_id=writer_checkpoint_timeout_peer"));
            messages.Add(LogLine($"event=filetransfer_receive_recovery_fallback_checkpoint_lifecycle_advanced; {checkpointScope}; checkpoint_binding_state=accepted"));
        }

        var result = await RunAnalyzeFixtureAsync(
            messages,
            [],
            compact
                ? new Dictionary<string, string>
                {
                    ["NLINK_FILETRANSFER_RETAINED_ANALYSIS_COMPACT"] = "1"
                }
                : null);

        Assert.True(
            result.Script.ExitCode == 0,
            result.Script.Stdout + Environment.NewLine + result.Script.Stderr);
        var verdict = ReadArtifactReport(
            result.ArtifactDir,
            "filetransfer-operator-verdict.txt");
        Assert.Equal(
            "14",
            verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing_raw_count"]);
        Assert.Equal(
            "1",
            verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing_distinct_count"]);
        Assert.Equal(
            "14",
            verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_delivered_peer_response_recheck_raw_count"]);
        Assert.Equal(
            recovered ? "1" : "0",
            verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_delivered_peer_response_recheck_recovered_count"]);
        Assert.Equal(
            recovered ? "0" : "1",
            verdict["filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_delivered_peer_response_recheck_unresolved_count"]);
        if (!recovered)
        {
            Assert.Equal(
                "filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing",
                verdict["first_proof_chain_failure_class"]);
            Assert.Equal(
                "delivered_receive_recovery_fallback_checkpoint_timeout_did_not_reauthorize_same_command",
                verdict["first_proof_chain_failure_reason"]);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task AnalyzeRetained_InitialActivationAnswerRequiresPeerDelivery(bool compact)
    {
        if (!OperatingSystem.IsWindows())
        {
            return;
        }

        const string responderScope =
            "session_id=sess_answer_delivery; payer_decision_id=41; generation=7; " +
            "log_writer_id=writer_responder";
        var result = await RunAnalyzeFixtureAsync(
            [
                LogLine($"event=tuna_acceleration_offer_received_raw; {responderScope}; msg_id=offer-1"),
                LogLine($"event=tuna_acceleration_answer_ack_pending; {responderScope}"),
                LogLine($"event=tuna_acceleration_answer_sent; {responderScope}; accepted=1; msg_id=answer-1"),
                LogLine($"event=tuna_acceleration_answer_replay_sent; {responderScope}; attempt=1; msg_id=answer-1"),
                LogLine($"event=tuna_acceleration_answer_ack_timeout; {responderScope}; trigger=runtime_unlock; retry_reason=runtime_unlock_answer_ack_timeout")
            ],
            [],
            compact
                ? new Dictionary<string, string>
                {
                    ["NLINK_FILETRANSFER_RETAINED_ANALYSIS_COMPACT"] = "1"
                }
                : null);

        Assert.True(result.Script.ExitCode == 0, result.Script.Stdout + Environment.NewLine + result.Script.Stderr);
        var verdict = ReadArtifactReport(result.ArtifactDir, "filetransfer-operator-verdict.txt");
        Assert.Equal("1", verdict["runtime_unlock_initial_activation_answer_peer_delivery_missing_raw_count"]);
        Assert.Equal("1", verdict["runtime_unlock_initial_activation_answer_peer_delivery_missing_distinct_count"]);
        Assert.Equal("0", verdict["runtime_unlock_initial_activation_answer_peer_delivery_missing_recovered_count"]);
        Assert.Equal("1", verdict["runtime_unlock_initial_activation_answer_peer_delivery_missing_unresolved_count"]);
        Assert.Equal("runtime_unlock_initial_activation_answer_peer_delivery_missing", verdict["first_proof_chain_failure_class"]);
        Assert.Equal("validated_offer_answer_not_delivered_to_initiator", verdict["first_proof_chain_failure_reason"]);
        Assert.Equal("route_runtime", verdict["acceptance_failure_class"]);
        Assert.Equal("fail", verdict["runtime_correctness_verdict"]);
        Assert.Equal("route_runtime", verdict["semantic_failure_domain"]);
    }

