                    "direction=outbound; source_route=regular_nkn_v4_fast; " +
                    "source_protocol_version=4; source_live_route_epoch=0; " +
                    "source_route_publication_generation=1; source_runtime_generation=1; " +
                    "source_terminal_generation=0; source_leg_generation=1; " +
                    "source_transport_epoch=0; source_bridge_recovery_generation=0; " +
                    "source_data_session_generation=1; send_kind=RegularV4Payload; " +
                    "log_writer_id=writer_outbound"
            ]);
        }

        var result = await RunAnalyzeFixtureAsync(
            messages.Select(message => LogLine(message)).ToArray(),
            ["-LiveRouteProofMode", "None"],
            compact
                ? new Dictionary<string, string>
                {
                    ["NLINK_FILETRANSFER_RETAINED_ANALYSIS_COMPACT"] = "1"
                }
                : null);

        Assert.True(
            result.Script.ExitCode == 0,
            result.Script.Stdout + Environment.NewLine + result.Script.Stderr);
        var verdict = ReadArtifactReport(
            result.ArtifactDir,
            "filetransfer-operator-verdict.txt");
        Assert.Equal(
            "1",
            verdict[
                "filetransfer_receive_recovery_completed_retained_proof_state_publication_missing_raw_count"]);
        Assert.Equal(
            "1",
            verdict[
                "filetransfer_receive_recovery_completed_retained_proof_state_publication_missing_distinct_count"]);
        Assert.Equal(
            recovered ? "1" : "0",
            verdict[
                "filetransfer_receive_recovery_completed_retained_proof_state_publication_missing_recovered_count"]);
        Assert.Equal(
            recovered ? "0" : "1",
            verdict[
                "filetransfer_receive_recovery_completed_retained_proof_state_publication_missing_unresolved_count"]);
        if (!recovered)
        {
            Assert.Equal(
                "filetransfer_receive_recovery_completed_retained_proof_state_publication_missing",
                verdict["first_proof_chain_failure_class"]);
            Assert.Equal(
                "session_liveness_proof_received",
                verdict["first_proof_chain_failure_event"]);
            Assert.Equal("14", verdict["first_proof_chain_failure_sequence"]);
            Assert.Equal("1727", verdict["first_proof_chain_failure_writer_sequence"]);
        }
    }

    [Theory]
    [InlineData(false, false, false)]
    [InlineData(true, false, false)]
    [InlineData(false, true, false)]
    [InlineData(true, true, false)]
    [InlineData(false, false, true)]
    [InlineData(true, false, true)]
    public async Task AnalyzeRetained_ReceiveRecoveryProofStateRecheckHeartbeatSuppressed_DeduplicatesAndRecovers(
        bool compact,
        bool recovered,
        bool proofBeforeSkip)
    {
        if (!OperatingSystem.IsWindows())
        {
            return;
        }

        const string sharedScope =
            "session_id=sess_recheck_suppressed; transfer_id=transfer_recheck_suppressed; " +
            "route=regular_nkn_v4_fast; protocol_version=4; live_route_epoch=0; " +
            "route_publication_generation=1; runtime_generation=1; terminal_generation=0; " +
            "leg_generation=1; transport_epoch=0; bridge_recovery_generation=0; " +
            "data_session_generation=1";
        const string inboundScope = sharedScope + "; direction=inbound; log_writer_id=writer_inbound";
        const string outboundScope = sharedScope + "; direction=outbound; log_writer_id=writer_outbound";
        const string inboundOperation =
            "receive_recovery_operation_generation=1; " +
            "receive_recovery_operation_authority_id=operation-inbound; bridge_decision_generation=1";
        const string outboundOperation =
            "receive_recovery_operation_generation=1; " +
            "receive_recovery_operation_authority_id=operation-outbound; bridge_decision_generation=1";
        List<string> messages =
        [
            $"event=filetransfer_receive_recovery_operation_issued; {inboundOperation}; {inboundScope}",
            $"event=filetransfer_receive_recovery_operation_execution_receipt_applied; {inboundOperation}; {inboundScope}; execution_outcome=Completed; closure_state=Retained; closure_generation=1",
            $"event=filetransfer_receive_recovery_operation_closure_retained; {inboundOperation}; {inboundScope}; execution_outcome=Completed; closure_state=Retained; closure_generation=1",
            $"event=filetransfer_receive_recovery_proof_state_publication_decided; {inboundOperation}; {inboundScope}; closure_generation=1; publication_generation=1; decision_status=Accepted",
            $"event=filetransfer_v4_state_sent; {inboundOperation}; {inboundScope}; closure_generation=1; repair_publication_kind=receive_recovery_proof_state; receive_recovery_publication_generation=1; epoch=225; v4_state_wire_fingerprint=wire-1",
            $"event=filetransfer_receive_recovery_proof_state_publication_receipt_applied; {inboundOperation}; {inboundScope}; closure_generation=1; publication_generation=1; publication_outcome=Delivered; decision_status=Accepted; v4_state_wire_fingerprint=wire-1",
            $"event=filetransfer_receive_recovery_proof_state_publication_recheck_armed; {inboundOperation}; {inboundScope}; closure_generation=1; closure_state=Retained; predecessor_publication_generation=1; predecessor_frame_fingerprint=wire-1",
            $"event=filetransfer_receive_recovery_operation_issued; {outboundOperation}; {outboundScope}",
            $"event=filetransfer_receive_recovery_operation_execution_receipt_applied; {outboundOperation}; {outboundScope}; execution_outcome=Completed; closure_state=Retained; closure_generation=1",
            $"event=filetransfer_receive_recovery_operation_closure_retained; {outboundOperation}; {outboundScope}; execution_outcome=Completed; closure_state=Retained; closure_generation=1"
        ];
        if (proofBeforeSkip)
        {
            messages.Add(
                $"event=filetransfer_receive_recovery_operation_proof_observed; {outboundOperation}; {outboundScope}; closure_generation=1; closure_state=Adopted; proof_identity=file_transfer_v4_state:225");
        }
        messages.AddRange(
        [
            "event=session_liveness_heartbeat_skipped_for_active_filetransfer_progress; session_id=sess_recheck_suppressed; transfer_id=transfer_recheck_suppressed; direction=outbound; progress_bytes=1677312; log_writer_id=writer_outbound; log_writer_sequence=2772",
            "event=session_liveness_heartbeat_skipped_for_active_filetransfer_progress; session_id=sess_recheck_suppressed; transfer_id=transfer_recheck_suppressed; direction=outbound; progress_bytes=1677312; log_writer_id=writer_outbound; log_writer_sequence=2773",
            "event=session_liveness_heartbeat_skipped_for_active_filetransfer_progress; session_id=sess_recheck_suppressed; transfer_id=transfer_recheck_suppressed; direction=outbound; progress_bytes=1677312; log_writer_id=writer_outbound; log_writer_sequence=2774"
        ]);
        if (recovered)
        {
            messages.AddRange(
            [
                $"event=session_liveness_heartbeat_required_for_receive_recovery_proof_state_recheck; {outboundScope}; recovery_state=BridgeRecoveryCompletedAwaitingProof; trigger=receive_recovery_completed_awaiting_proof; progress_bytes=1677312",
                "event=session_liveness_heartbeat_sent; session_id=sess_recheck_suppressed; generation=1; sequence=19; delivered_any=1; log_writer_id=writer_outbound",
                "event=session_liveness_heartbeat_received; session_id=sess_recheck_suppressed; generation=1; sequence=19; lane=control; log_writer_id=writer_inbound",
                "event=session_liveness_proof_received; session_id=sess_recheck_suppressed; generation=1; sequence=19; proof_kind=heartbeat_received; lane=control; log_writer_id=writer_inbound",
                $"event=filetransfer_receive_recovery_proof_state_publication_recheck_decided; {inboundOperation}; {inboundScope}; closure_generation=1; predecessor_publication_generation=1; heartbeat_generation=1; heartbeat_sequence=19; proof_kind=heartbeat_received; lane=control; publication_generation=2; decision_status=Accepted",
                $"event=filetransfer_v4_state_sent; {inboundOperation}; {inboundScope}; closure_generation=1; repair_publication_kind=receive_recovery_proof_state; receive_recovery_publication_generation=2; receive_recovery_publication_attempt=post_delivery_recheck; epoch=226; v4_state_wire_fingerprint=wire-2",
                $"event=filetransfer_receive_recovery_proof_state_publication_receipt_applied; {inboundOperation}; {inboundScope}; closure_generation=1; publication_generation=2; publication_outcome=Delivered; decision_status=Accepted; v4_state_wire_fingerprint=wire-2",
                $"event=filetransfer_v4_state_received; {outboundScope}; epoch=226; v4_state_wire_fingerprint=wire-2; applied=1",
                $"event=filetransfer_receive_recovery_operation_proof_observed; {outboundOperation}; {outboundScope}; closure_generation=1; closure_state=Adopted; proof_identity=file_transfer_v4_state:226",
                $"event=filetransfer_receive_recovery_operation_closure_adopted; {outboundOperation}; {outboundScope}; closure_generation=1; closure_state=Adopted; proof_identity=file_transfer_v4_state:226",
                $"event=filetransfer_bridge_recovery_payload_submission_resumed; {outboundOperation}; {outboundScope}; closure_generation=1; closure_state=Adopted; proof_identity=file_transfer_v4_state:226"
            ]);
        }

        var result = await RunAnalyzeFixtureAsync(
            messages.Select(message => LogLine(message)).ToArray(),
            ["-LiveRouteProofMode", "None"],
            compact
                ? new Dictionary<string, string>
                {
                    ["NLINK_FILETRANSFER_RETAINED_ANALYSIS_COMPACT"] = "1"
                }
                : null);

        Assert.True(result.Script.ExitCode == 0, result.Script.Stdout + Environment.NewLine + result.Script.Stderr);
        var verdict = ReadArtifactReport(result.ArtifactDir, "filetransfer-operator-verdict.txt");
        Assert.Equal(proofBeforeSkip ? "0" : "3", verdict["filetransfer_receive_recovery_completed_retained_proof_state_recheck_heartbeat_suppressed_raw_count"]);
        Assert.Equal(proofBeforeSkip ? "0" : "1", verdict["filetransfer_receive_recovery_completed_retained_proof_state_recheck_heartbeat_suppressed_distinct_count"]);
        Assert.Equal(!proofBeforeSkip && recovered ? "1" : "0", verdict["filetransfer_receive_recovery_completed_retained_proof_state_recheck_heartbeat_suppressed_recovered_count"]);
        Assert.Equal(!proofBeforeSkip && !recovered ? "1" : "0", verdict["filetransfer_receive_recovery_completed_retained_proof_state_recheck_heartbeat_suppressed_unresolved_count"]);
        if (!proofBeforeSkip && !recovered)
        {
            Assert.Equal(
                "filetransfer_receive_recovery_completed_retained_proof_state_recheck_heartbeat_suppressed",
                verdict["first_proof_chain_failure_class"]);
            Assert.Equal(
                "session_liveness_heartbeat_skipped_for_active_filetransfer_progress",
                verdict["first_proof_chain_failure_event"]);
            Assert.Equal("2772", verdict["first_proof_chain_failure_writer_sequence"]);
        }
    }

    [Theory]
    [InlineData(false, false, "valid")]
    [InlineData(false, true, "valid")]
    [InlineData(true, false, "valid")]
    [InlineData(true, true, "valid")]
    [InlineData(false, false, "stage_only")]
    [InlineData(true, false, "stage_only")]
    [InlineData(false, false, "stale_receipt")]
    [InlineData(true, false, "stale_receipt")]
    [InlineData(false, false, "rejected_commit")]
    [InlineData(true, false, "rejected_commit")]
    [InlineData(false, false, "mutated_receipt_scope")]
    [InlineData(true, false, "mutated_receipt_scope")]
    [InlineData(false, false, "mutated_phase2_scope")]
    [InlineData(true, false, "mutated_phase2_scope")]
    [InlineData(false, false, "retained_only")]
    [InlineData(true, false, "retained_only")]
    [InlineData(false, false, "adopted_only")]
    [InlineData(true, false, "adopted_only")]
    public async Task AnalyzeRetained_ReceiveRecoveryOperation_HasFullCompactAndArrivalOrderParity(
        bool compact,
        bool proofFirst,
        string phase2Mode)
    {
        if (!OperatingSystem.IsWindows())
        {
            return;
        }

        const string transferId = "transfer_receive_recovery_operation";
        const string sessionId = "sess_runtime_unlock_dispatch_proof";
        const string scope =
            $"session_id={sessionId}; transfer_id={transferId}; direction=outbound; " +
            "route=regular_nkn_v4_fast; protocol_version=4; live_route_epoch=1; " +
            "route_publication_generation=6; runtime_generation=4; terminal_generation=0; " +
            "leg_generation=9; transport_epoch=2; bridge_recovery_generation=3; " +
            "data_session_generation=11";
        static string OperationLine(string eventName, int generation, string scope, string suffix)
        {
            var bridgeDecisionGeneration = generation + 4;
            var leaseGeneration = generation == 1 ? 3 : 0;
            var leaseAuthorityId = generation == 1
                ? "fta2-recovery-lease-3"
                : "(none)";
            return
                $"event={eventName}; receive_recovery_operation_generation={generation}; " +
                $"receive_recovery_operation_authority_id=fta2-receive-recovery-operation-{generation}; " +
                $"observation_identity=receive-recovery-observation-{generation}; " +
                $"observation_generation={generation}; observation_source=test; " +
                $"observation_reason=test_receive_recovery; observation_utc_ms={1000 + generation}; " +
                $"{scope}; route_commit_generation=0; route_commit_transaction_generation=0; " +
                "route_commit_offer_generation=0; route_commit_path_lease_generation=0; " +
                "route_commit_probe_ack_id=(none); checkpoint_request_id=(none); " +
                "data_session_identity=data-session-11; " +
                $"bridge_decision_generation={bridgeDecisionGeneration}; " +
                $"recovery_liveness_lease_authority_id={leaseAuthorityId}; " +
                $"recovery_liveness_lease_generation={leaseGeneration}; {suffix}";
        }

        var completedReceipt = OperationLine(
            "filetransfer_receive_recovery_operation_execution_receipt_applied",
            1,
            scope,
            "execution_outcome=Completed; execution_mode=soft_then_hard; bridge_decision_generation=5; regular_v4_liveness_generation=3" +
            (string.Equals(
                phase2Mode,
                "mutated_receipt_scope",
                StringComparison.Ordinal)
                ? "; data_session_identity=other-data-session"
                : string.Empty));
        var proofObserved = OperationLine(
            "filetransfer_receive_recovery_operation_proof_observed",
            1,
            scope,
            "proof_identity=receive-proof-1; proof_observed_utc_ms=1010; " +
            "bridge_decision_generation=5; regular_v4_liveness_generation=3");
        var retainedOnly = string.Equals(
            phase2Mode,
            "retained_only",
            StringComparison.Ordinal);
        var adoptedOnly = string.Equals(
            phase2Mode,
            "adopted_only",
            StringComparison.Ordinal);
        var messages = new List<string>
        {
            OperationLine(
                "filetransfer_receive_recovery_operation_issued",
                1,
                scope,
                "operation_state=Issued; bridge_decision_generation=5; regular_v4_liveness_generation=3"),
            OperationLine(
                "filetransfer_receive_recovery_operation_issued",
                1,
                scope,
                "operation_state=Issued; bridge_decision_generation=5; regular_v4_liveness_generation=3; decision_status=Idempotent"),
            OperationLine(
                "filetransfer_receive_recovery_operation_execution_start_decided",
                1,
                scope,
                "execution_start_status=Started; bridge_decision_generation=5; regular_v4_liveness_generation=3")
        };
        if (retainedOnly)
        {
            messages.Add(completedReceipt);
            messages.Add(
                OperationLine(
                    "filetransfer_receive_recovery_operation_closure_retained",
                    1,
                    scope,
                    "closure_generation=1; closure_state=Retained; bridge_decision_generation=5; regular_v4_liveness_generation=3"));
        }
        else if (proofFirst)
        {
            messages.Add(proofObserved);
            messages.Add(completedReceipt);
            messages.Add(
                OperationLine(
                    "filetransfer_receive_recovery_operation_closure_adopted",
                    1,
                    scope,
                    "closure_generation=1; closure_state=Adopted; bridge_decision_generation=5; regular_v4_liveness_generation=3"));
        }
        else
        {
            messages.Add(completedReceipt);
            messages.Add(
                OperationLine(
                    "filetransfer_receive_recovery_operation_closure_retained",
                    1,
                    scope,
                    "closure_generation=1; closure_state=Retained; bridge_decision_generation=5; regular_v4_liveness_generation=3"));
            messages.Add(proofObserved);
            messages.Add(
                OperationLine(
                    "filetransfer_receive_recovery_operation_closure_adopted",
                    1,
                    scope,
                    "closure_generation=1; closure_state=Adopted; bridge_decision_generation=5; regular_v4_liveness_generation=3"));
            }

        const string receiveRecoveryRelease =
            "; release_kind=ReceiveRecoveryLeaseClosure" +
            "; release_authority_id=fta2-recovery-lease-3" +
            "; release_generation=3; release_outcome=Retired" +
            "; receive_recovery_operation_generation=1" +
            "; data_session_generation=11";
        if (!retainedOnly && !adoptedOnly)
        {
            messages.Add(
                OperationLine(
                    "filetransfer_receive_recovery_operation_closure_reserved",
                    1,
                    scope,
                    "closure_generation=1; closure_state=Reserved; " +
                    "retry_authority_id=fta2-runtime-unlock-test-1; " +
                    "retry_dispatch_attempt_generation=1; retry_missing_dispatch_generation=0; " +
                    "retry_release_kind=ReceiveRecoveryLeaseClosure; " +
                    "retry_release_authority_id=fta2-recovery-lease-3; " +
                    "retry_release_generation=3; retry_release_outcome=Retired; " +
                    "retry_install_generation=0"));
            var phase2Lines = new List<string>
            {
                RuntimeUnlockRetryInstallLine(
                    "runtime_unlock_retry_dispatch_decision_staged",
                    transferId,
                    "; stage_status=Staged; decision_status=Granted" +
                    receiveRecoveryRelease,
                    "retry_dispatch_decision_staged")
            };
            if (!string.Equals(phase2Mode, "stage_only", StringComparison.Ordinal))
            {
                var evidenceInstallGeneration =
                    string.Equals(
                        phase2Mode,
                        "stale_receipt",
                        StringComparison.Ordinal)
                        ? 2
                        : 1;
                var phase2ScopeMutation = string.Equals(
                    phase2Mode,
                    "mutated_phase2_scope",
                    StringComparison.Ordinal)
                    ? "; data_session_generation=12"
                    : string.Empty;
                phase2Lines.Add(
                    RuntimeUnlockRetryInstallLine(
                        "runtime_unlock_retry_dispatch_install_receipt_issued",
                        transferId,
                        "; stage_status=Staged; decision_status=Granted" +
                        receiveRecoveryRelease +
                        phase2ScopeMutation,
                        "retry_dispatch_install_receipt_issued",
                        installGeneration: evidenceInstallGeneration));
                phase2Lines.Add(
                    RuntimeUnlockRetryInstallLine(
                        "runtime_unlock_retry_dispatch_install_committed",
                        transferId,
                        $"; install_status={(string.Equals(phase2Mode, "rejected_commit", StringComparison.Ordinal) ? "Rejected" : "Installed")}; decision_status=Granted" +
                        receiveRecoveryRelease +
                        phase2ScopeMutation,
                        "retry_dispatch_install_committed",
                        installGeneration: evidenceInstallGeneration));
            }
            phase2Lines.Add(
                RuntimeUnlockRetryInstallLine(
                    "runtime_unlock_retry_dispatch_authority_granted",
                    transferId,
                    "; install_status=Installed; decision_status=Granted" +
                    receiveRecoveryRelease,
                    "runtime_unlock_retry_dispatch_authority_granted"));
            foreach (var phase2Line in phase2Lines)
            {
                messages.Add(phase2Line);
            }
            messages.Add(
                OperationLine(
                    "filetransfer_receive_recovery_operation_closure_consumed",
                    1,
                    scope,
                    "closure_generation=1; closure_state=Consumed; " +
                    "retry_authority_id=fta2-runtime-unlock-test-1; " +
                    "retry_dispatch_attempt_generation=1; retry_missing_dispatch_generation=0; " +
                    "retry_release_kind=ReceiveRecoveryLeaseClosure; " +
                    "retry_release_authority_id=fta2-recovery-lease-3; " +
                    "retry_release_generation=3; retry_release_outcome=Retired; " +
                    "retry_install_generation=1"));
        }

        // Compatibility telemetry for the same coordinator operation must not
        // create a second legacy recovery-lease failure.
        messages.Add(
            $"event=runtime_unlock_regular_v4_recovery_lifecycle_decided; {scope}; " +
            "regular_v4_liveness_generation=3; bridge_decision_generation=5; " +
            "lifecycle_outcome=Completed; decision_status=Accepted");
        messages.Add(
            $"event=runtime_unlock_regular_v4_recovery_lease_closure_rejected; {scope}; " +
            "regular_v4_liveness_generation=3; bridge_decision_generation=5; " +
            "lifecycle_outcome=Completed; decision_status=Accepted; " +
            "mismatch_kind=coordinator_recovery_liveness_lease_stale; " +
            "decision_reason=coordinator_recovery_liveness_lease_stale");

        messages.AddRange(
        [
            OperationLine(
                "filetransfer_receive_recovery_operation_issued",
                2,
                scope,
                "operation_state=Issued; bridge_decision_generation=6"),
            OperationLine(
                "filetransfer_receive_recovery_operation_execution_start_decided",
                2,
                scope,
                "execution_start_status=Started; bridge_decision_generation=6"),
            OperationLine(
                "filetransfer_receive_recovery_operation_execution_receipt_applied",
                2,
                scope,
                "execution_outcome=Discarded; execution_mode=soft; bridge_decision_generation=6"),
            OperationLine(
                "filetransfer_receive_recovery_operation_issued",
                3,
                scope,
                "operation_state=Issued; bridge_decision_generation=7"),
            OperationLine(
                "filetransfer_receive_recovery_operation_execution_start_decided",
                3,
                scope,
                "execution_start_status=Started; bridge_decision_generation=7"),
            OperationLine(
                "filetransfer_receive_recovery_evaluation_requested",
                3,
                scope,
                "source=bridge_started_ttl; reason=missing_callback"),
            OperationLine(
                "filetransfer_receive_recovery_operation_invalidated",
                3,
                scope,
                "invalidation_reason=missing_callback_ttl"),
            OperationLine(
                "filetransfer_receive_recovery_operation_issued",
                4,
                scope,
                "operation_state=Issued; bridge_decision_generation=8"),
            OperationLine(
                "filetransfer_receive_recovery_operation_invalidated",
                4,
                scope,
                "invalidation_reason=coordinator_terminalized; bridge_decision_generation=8"),
            OperationLine(
                "filetransfer_receive_recovery_operation_issued",
                5,
                scope,
                "operation_state=Issued; bridge_decision_generation=9"),
            OperationLine(
                "filetransfer_receive_recovery_operation_execution_receipt_applied",
                5,
                scope,
                "execution_outcome=Discarded; execution_mode=(none); bridge_decision_generation=9"),
            $"event=file_transfer_outbound_terminal; session_id={sessionId}; transfer_id={transferId}; direction=outbound; state=Failed; error_code=timeout"
        ]);

        var result = await RunAnalyzeFixtureAsync(
            messages.Select(message => LogLine(message)).ToArray(),
            ["-LiveRouteProofMode", "None"],
            compact
                ? new Dictionary<string, string>
                {
                    ["NLINK_FILETRANSFER_RETAINED_ANALYSIS_COMPACT"] = "1"
                }
                : null);

        Assert.True(result.Script.ExitCode == 0, result.Script.Stdout + Environment.NewLine + result.Script.Stderr);
        var verdict = ReadArtifactReport(result.ArtifactDir, "filetransfer-operator-verdict.txt");
        Assert.Equal("6", verdict["filetransfer_receive_recovery_operation_raw_count"]);
        Assert.Equal("5", verdict["filetransfer_receive_recovery_operation_distinct_count"]);
        var validPhase2 =
            string.Equals(phase2Mode, "valid", StringComparison.Ordinal);
        Assert.Equal(
            validPhase2 ? "4" : "3",
            verdict["filetransfer_receive_recovery_operation_recovered_count"]);
        Assert.Equal(
            validPhase2 ? "1" : "2",
            verdict["filetransfer_receive_recovery_operation_unresolved_count"]);
        Assert.Equal("fail", verdict["filetransfer_receive_recovery_operation_verdict"]);
        Assert.Equal("3", verdict["filetransfer_receive_recovery_operation_started_count"]);
        Assert.Equal("3", verdict["filetransfer_receive_recovery_operation_execution_receipt_applied_count"]);
        Assert.Equal(
            retainedOnly ? "0" : "1",
            verdict["filetransfer_receive_recovery_operation_proof_observed_count"]);
        Assert.Equal(
            proofFirst ? "0" : "1",
            verdict["filetransfer_receive_recovery_operation_closure_retained_count"]);
        Assert.Equal(
            retainedOnly ? "0" : "1",
            verdict["filetransfer_receive_recovery_operation_closure_adopted_count"]);
        Assert.Equal(
            retainedOnly || adoptedOnly ? "0" : "1",
            verdict["filetransfer_receive_recovery_operation_closure_reserved_count"]);
        Assert.Equal(
            retainedOnly || adoptedOnly ? "0" : "1",
            verdict["filetransfer_receive_recovery_operation_closure_consumed_count"]);
        Assert.Equal(
            "0",
            verdict["runtime_unlock_regular_v4_recovery_lease_not_issued_unresolved_count"]);
        Assert.Equal(
            "0",
            verdict["runtime_unlock_regular_v4_recovery_lease_closure_liveness_not_preserved_unresolved_count"]);
        Assert.Equal(
            "filetransfer_receive_recovery_operation_incomplete",
            verdict["first_proof_chain_failure_class"]);
        Assert.Equal(
            validPhase2
                ? "filetransfer_receive_recovery_operation_invalidated"
                : retainedOnly
                    ? "filetransfer_receive_recovery_operation_closure_retained"
                    : adoptedOnly
                        ? "filetransfer_receive_recovery_operation_closure_adopted"
                        : "filetransfer_receive_recovery_operation_closure_consumed",
            verdict["first_proof_chain_failure_event"]);
        Assert.Equal("route_runtime", verdict["acceptance_failure_class"]);
        Assert.Equal("route_runtime", verdict["semantic_failure_domain"]);
        Assert.Equal("FAIL_PROTOCOL_OR_INTEGRITY", verdict["verdict"]);
    }

    [Fact]
    public async Task ReceiveRecoveryOperationCorrelation_IndexesSemanticInputOnceAndUsesBoundedOperationLookups()
    {
        if (!OperatingSystem.IsWindows())
        {
            return;
        }

        const string scriptText = """
            param([string]$RepoRoot)
            $ErrorActionPreference = 'Stop'
            Set-StrictMode -Version Latest
            . (Join-Path $RepoRoot 'tools/FileTransferSoak/LogParsing.ps1')
            . (Join-Path $RepoRoot 'tools/FileTransferSoak/ArtifactWriters.ps1')

            function New-TestEvent {
                param([string]$Name, [long]$Sequence, [hashtable]$Fields)
                return [pscustomobject]@{
                    EventName = $Name
                    Sequence = $Sequence
                    LineNumber = $Sequence
                    Fields = $Fields
                }
            }

            $operationCount = 16
            $unrelatedCount = 50000
            $eventsPerOperation = 4
            [object[]]$events = [object[]]::new(
                ($operationCount * $eventsPerOperation) + $unrelatedCount)
            $cursor = 0
            for ($generation = 1; $generation -le $operationCount; $generation++) {
                $scope = @{
                    receive_recovery_operation_generation = [string]$generation
                    receive_recovery_operation_authority_id = "receive-recovery-$generation"
                    observation_identity = "observation-$generation"
                    observation_generation = [string]$generation
                    observation_source = 'synthetic_test'
                    observation_reason = 'synthetic_recovery'
                    observation_utc_ms = [string](1000 + $generation)
                    session_id = 'session-recovery-index'
                    transfer_id = "transfer-recovery-index-$generation"
                    direction = 'inbound'
                    route = 'post_tuna_fallback_v6'
                    protocol_version = '6'
                    live_route_epoch = '1'
                    route_publication_generation = '2'
                    route_commit_generation = '1'
                    route_commit_transaction_generation = '1'
                    route_commit_offer_generation = '1'
                    route_commit_path_lease_generation = '1'
                    route_commit_probe_ack_id = "probe-$generation"
                    runtime_generation = '3'
                    terminal_generation = '0'
                    leg_generation = '4'
                    transport_epoch = '2'
                    bridge_recovery_generation = '1'
                    bridge_decision_generation = [string](10 + $generation)
                    checkpoint_request_id = "checkpoint-$generation"
                    data_session_identity = "data-session-$generation"
                    data_session_generation = '1'
                    recovery_liveness_lease_authority_id = '(none)'
                    recovery_liveness_lease_generation = '0'
                }
                $issued = $scope.Clone()
                $issued.operation_state = 'Issued'
                $events[$cursor++] = New-TestEvent `
                    'filetransfer_receive_recovery_operation_issued' `
                    ($generation * 10L) `
                    $issued

                $started = $scope.Clone()
                $started.execution_start_status = 'Started'
                $events[$cursor++] = New-TestEvent `
                    'filetransfer_receive_recovery_operation_execution_start_decided' `
                    (($generation * 10L) + 1L) `
                    $started

                $receipt = $scope.Clone()
                $receipt.execution_outcome = 'Completed'
                $receipt.execution_mode = 'hard'
                $events[$cursor++] = New-TestEvent `
                    'filetransfer_receive_recovery_operation_execution_receipt_applied' `
                    (($generation * 10L) + 2L) `
                    $receipt

                $proof = $scope.Clone()
                $proof.proof_identity = "receive-proof-$generation"
                $proof.proof_observed_utc_ms = [string](2000 + $generation)
                $events[$cursor++] = New-TestEvent `
                    'filetransfer_receive_recovery_operation_proof_observed' `
                    (($generation * 10L) + 3L) `
                    $proof
            }

            $unrelated = New-TestEvent `
                'session_liveness_heartbeat_sent' `
                1000000L `
                @{
                    session_id = 'unrelated-session'
                    trigger = 'periodic'
                }
            while ($cursor -lt $events.Length) {
                $events[$cursor++] = $unrelated
            }

            $result = Get-FileTransferReceiveRecoveryOperationCorrelation -Events $events
            $expectedInputCount = [long]$events.Length
            $maximumBoundedLookups = [long]$operationCount * 64L
            if ([long]$result.RawCount -ne $operationCount -or
                [long]$result.DistinctCount -ne $operationCount -or
                [long]$result.RecoveredCount -ne $operationCount -or
                [long]$result.UnresolvedCount -ne 0L -or
                [long]$result.IndexBuildVisitCount -ne $expectedInputCount -or
                [long]$result.BoundedLookupVisitCount -gt $maximumBoundedLookups) {
                throw "unexpected receive-recovery index result: $($result | ConvertTo-Json -Compress)"
            }
            Write-Output 'receive-recovery-operation-index-bounded-ok'
            """;

        var result = await RunPowerShellScriptTextAsync(scriptText, [FindRepoRoot()]);
        Assert.True(
            result.ExitCode == 0,
            $"Receive-recovery operation index test failed.{Environment.NewLine}{result.Stdout}{Environment.NewLine}{result.Stderr}");
        Assert.Contains(
            "receive-recovery-operation-index-bounded-ok",
            result.Stdout,
            StringComparison.Ordinal);
    }

    [Fact]
    public async Task ReceiveRecoverySemanticCorrelators_ReuseOneChronologicalInput_WithParity()
    {
        if (!OperatingSystem.IsWindows())
        {
            return;
        }

        const string scriptText = """
            param([string]$RepoRoot)
            $ErrorActionPreference = 'Stop'
            Set-StrictMode -Version Latest
            . (Join-Path $RepoRoot 'tools/FileTransferSoak/LogParsing.ps1')
            . (Join-Path $RepoRoot 'tools/FileTransferSoak/ArtifactWriters.ps1')

            function New-TestEvent {
                param([long]$Sequence)
                return [pscustomobject]@{
                    EventName = 'synthetic_receive_recovery_diagnostic'
                    Sequence = $Sequence
                    LineNumber = $Sequence
                    FilePath = 'synthetic-recovery-semantic.log'
                    Fields = @{
                        session_id = 'session-semantic-order'
                        transfer_id = 'transfer-semantic-order'
                        direction = 'outbound'
                    }
                }
            }

            [object[]]$events = @(
                (New-TestEvent 30),
                (New-TestEvent 10),
                (New-TestEvent 20))
            [object[]]$ordered = @($events | Sort-Object Sequence, LineNumber)
            [string[]]$functions = @(
                'Get-FileTransferReceiveRecoveryCompletedUnprovenPayloadHoldCorrelation',
                'Get-FileTransferReceiveRecoveryCompletedRetainedProofStatePublicationCorrelation',
                'Get-FileTransferReceiveRecoveryCompletedRetainedProofStateRecheckHeartbeatSuppressionCorrelation',
                'Get-FileTransferReceiveRecoveryCompletedUnprovenSuccessorCorrelation',
                'Get-FileTransferReceiveRecoveryCompletedProvenSuccessorCorrelation',
                'Get-FileTransferRuntimeUnlockRegularV4RecoveryLeaseCorrelation',
                'Get-FileTransferBridgeRecoveryExecutionSoftToHardHandoffCorrelation',
                'Get-FileTransferBridgeRecoveryExecutionStartupPayloadIsolationCorrelation',
                'Get-FileTransferBridgeRecoveryExecutionPayloadHoldWithPostTunaCorrelation',
                'Get-FileTransferRuntimeUnlockRegularV4RecoveryClosureOfferTimeoutCorrelation',
                'Get-FileTransferRuntimeUnlockInitialOfferRetryLifecycleHandoffCorrelation',
                'Get-FileTransferRuntimeUnlockInitialActivationAnswerPeerDeliveryCorrelation',
                'Get-FileTransferRuntimeUnlockInitialOfferReceiveRecoveryHoldCorrelation',
                'Get-FileTransferRuntimeUnlockInitialActivationReceiveRecoveryHoldReleaseDeliveryCorrelation',
                'Get-FileTransferRuntimeUnlockInitialActivationReceiveRecoveryHoldReleasedPathLeaseExpiredCorrelation',
                'Get-FileTransferRuntimeUnlockInitialActivationReceiveRecoveryHoldReleasedOfferExpiredCorrelation')

            foreach ($functionName in $functions) {
                $command = Get-Command $functionName -CommandType Function
                if (-not $command.Parameters.ContainsKey('AlreadyChronologicallyOrdered')) {
                    throw "$functionName does not expose the shared-order boundary"
                }
                $baseline = & $functionName -Events $events
                $optimized = & $functionName `
                    -Events $ordered `
                    -AlreadyChronologicallyOrdered
                $baselineJson = $baseline | ConvertTo-Json -Depth 20 -Compress
                $optimizedJson = $optimized | ConvertTo-Json -Depth 20 -Compress
                if ($baselineJson -cne $optimizedJson) {
                    throw "$functionName changed output under shared chronological input"
                }
            }

            $orchestration = Get-Content `
                -LiteralPath (Join-Path $RepoRoot 'tools/FileTransferOps/AnalyzerOrchestration.ps1') `
                -Raw
            $start = $orchestration.IndexOf(
                '[object[]]$runtimeUnlockRegularV4RecoveryOrderedEvents',
                [System.StringComparison]::Ordinal)
            $end = $orchestration.IndexOf(
                '[object[]]$runtimeUnlockRetryDispatchAuthorityTupleMismatchEvents',
                $start,
                [System.StringComparison]::Ordinal)
            if ($start -lt 0 -or $end -le $start) {
                throw 'shared receive-recovery orchestration boundary missing'
            }
            $boundary = $orchestration.Substring($start, $end - $start)
            foreach ($functionName in $functions) {
                $functionOffset = $boundary.IndexOf($functionName, [System.StringComparison]::Ordinal)
                if ($functionOffset -lt 0) {
                    throw "$functionName is missing from the shared-order boundary"
                }
                $callEnd = [Math]::Min($boundary.Length, $functionOffset + 500)
                $callText = $boundary.Substring($functionOffset, $callEnd - $functionOffset)
                if ($callText.IndexOf(
                        '-AlreadyChronologicallyOrdered',
                        [System.StringComparison]::Ordinal) -lt 0) {
                    throw "$functionName does not consume the shared chronological input"
                }
            }
            if ([regex]::Matches(
                    $boundary,
                    'Sort-Object Sequence, LineNumber',
                    [System.Text.RegularExpressions.RegexOptions]::CultureInvariant).Count -ne 1) {
                throw 'receive-recovery semantic boundary must sort its shared input exactly once'
            }
            Write-Output 'receive-recovery-semantic-shared-order-parity-ok'
            """;

        var result = await RunPowerShellScriptTextAsync(scriptText, [FindRepoRoot()]);
        Assert.True(
            result.ExitCode == 0,
            $"Receive-recovery semantic shared-order test failed.{Environment.NewLine}{result.Stdout}{Environment.NewLine}{result.Stderr}");
        Assert.Contains(
            "receive-recovery-semantic-shared-order-parity-ok",
            result.Stdout,
            StringComparison.Ordinal);
    }

